import sys, heapq
from collections import deque, defaultdict

def longest_uniform_run(s, lock, k):
    best = 0
    for c in set(s):
        left = bad = locked_bad = 0
        for right, ch in enumerate(s):
            if ch != c:
                bad += 1
                if lock[right] == '1':
                    locked_bad += 1
            while bad > k or locked_bad > 0:
                if s[left] != c:
                    bad -= 1
                    if lock[left] == '1':
                        locked_bad -= 1
                left += 1
            best = max(best, right - left + 1)
    return best

