import sys, heapq
from collections import deque, defaultdict

def build_order(n, deps, target):
    need = defaultdict(list)
    for a, b in deps:
        need[a].append(b)
    seen = {target}
    stack = [target]
    while stack:
        x = stack.pop()
        for y in need[x]:
            if y not in seen:
                seen.add(y)
                stack.append(y)
    indeg = {x: 0 for x in seen}
    users = defaultdict(list)
    for a, b in set(deps):
        if a in seen:
            indeg[a] += 1
            users[b].append(a)
    heap = [x for x in seen if indeg[x] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        x = heapq.heappop(heap)
        order.append(x)
        for u in users[x]:
            indeg[u] -= 1
            if indeg[u] == 0:
                heapq.heappush(heap, u)
    if len(order) != len(seen):
        return "-1"
    return " ".join(map(str, order))

x = list(map(int, sys.stdin.read().split()))
if x:
    n, m, t = x[0], x[1], x[2]
    print(build_order(n, [(x[3 + 2 * i], x[4 + 2 * i]) for i in range(m)], t))

