import sys, heapq
from collections import deque, defaultdict

def transform_cost(a, b, ins, dele, rep):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        dp[i][0] = i * dele
    for j in range(1, n + 1):
        dp[0][j] = j * ins
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j] + dele, dp[i][j - 1] + ins, dp[i - 1][j - 1] + rep)
    return dp[m][n]

